insert into public.projects (slug, title, tagline, location, status, image, summary, body, facts, progress, milestones, gallery, sort_order, published) values
  ('internat-jeunes-filles', 'Internat pour jeunes filles', 'Un toit sûr pour apprendre un métier', 'Togo', 'en-cours', '{"src":"/images/inauguration-ruban.webp","alt":"Coupe du ruban devant le bâtiment de l''internat, en présence d''un représentant de l''ambassade d''Allemagne","width":1600,"height":1066}'::jsonb, 'Un internat en blocs de terre comprimée pour héberger les apprenties venues de loin, afin qu''aucune jeune fille ne renonce à sa formation faute de logement.', array['Beaucoup de jeunes filles abandonnent leur apprentissage parce que le centre de formation est trop loin de chez elles. Les trajets quotidiens coûtent cher et les exposent à des risques. L''internat leur offre un cadre de vie sûr, à deux pas de leur lieu de formation.', 'Le bâtiment, d''environ 300 m², est construit en blocs de terre comprimée (BTC). Ce matériau local et durable garde la fraîcheur. L''architecture est pensée pour le climat tropical : éclairage naturel, ventilation et gestion thermique limitent les besoins en énergie. Il compte 16 chambres de 4 lits et a été conçu pour pouvoir s''agrandir.', 'Le 13 avril 2023, la fête des ouvriers (« Richtfest », une tradition allemande qui célèbre l''achèvement du gros œuvre) a réuni les partenaires, dont Togohilfe, un représentant de l''ambassade d''Allemagne et la Chambre des métiers de Cologne. Les autorités administratives, traditionnelles et religieuses étaient également présentes.', 'Fin 2025, le premier bloc a été achevé. Il peut accueillir 24 apprenties.']::text[], '[{"label":"Surface","value":"≈ 300 m²"},{"label":"Chambres","value":"16 chambres de 4 lits"},{"label":"Matériau","value":"Blocs de terre comprimée (BTC)"},{"label":"Premier bloc","value":"24 apprenties, achevé fin 2025"}]'::jsonb, '{"label":"Places disponibles","current":24,"target":64,"unit":"lits"}'::jsonb, '[{"date":"2023-04-13","text":"Fête des ouvriers (Richtfest) avec les partenaires et les autorités"},{"date":"2025-12-01","text":"Achèvement du premier bloc : 24 places pour les apprenties"}]'::jsonb, '[{"src":"/images/inauguration-ruban.webp","alt":"Coupe du ruban devant le bâtiment de l''internat, en présence d''un représentant de l''ambassade d''Allemagne","width":1600,"height":1066},{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066},{"src":"/images/invites-ceremonie.webp","alt":"Invités et partenaires togolais et allemands assis sous le chapiteau pendant la cérémonie","width":1600,"height":1066},{"src":"/images/photo-groupe-ouvriers.webp","alt":"Photo de groupe des officiels, partenaires et ouvriers en casques jaunes sous le chapiteau","width":850,"height":560}]'::jsonb, 0, true),
  ('cefopexd', 'Centre de formation CEFOPEXD', 'Apprendre un métier pour gagner sa vie', 'Devikinme', 'en-cours', '{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066}'::jsonb, 'Le centre de formation de Devikinme offre aux jeunes sortis de l''école une formation professionnelle qui leur permet de gagner leur vie.', array['Au Togo, de nombreux jeunes quittent l''école sans qualification. Le CEFOPEXD (Devikinme) leur propose une formation professionnelle concrète, tournée vers l''emploi et la création d''activité.', 'La formation associe pratique en atelier et enseignements théoriques. Elle s''appuie sur l''expérience des partenaires allemands de l''artisanat, notamment la Chambre des métiers de Cologne.', 'Les apprenants sont accompagnés jusqu''à leur insertion : recherche d''emploi, installation à leur compte et appui technique aux jeunes entrepreneurs.']::text[], '[{"label":"Lieu","value":"Devikinme, Togo"},{"label":"Public","value":"Jeunes sortis de l''école"},{"label":"Approche","value":"Formation pratique et bilingue"},{"label":"Objectif","value":"Insertion et création d''entreprise"}]'::jsonb, null, '[]'::jsonb, '[{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066},{"src":"/images/photo-groupe-ouvriers.webp","alt":"Photo de groupe des officiels, partenaires et ouvriers en casques jaunes sous le chapiteau","width":850,"height":560},{"src":"/images/plantation-partenaires.webp","alt":"Plantation d''un arbuste avec des partenaires allemands, une apprentie et les ouvriers du chantier","width":1600,"height":1066}]'::jsonb, 1, true),
  ('femmes-solaires', 'Femmes solaires', 'L''énergie du soleil entre les mains des femmes', 'Togo', 'en-cours', '{"src":"/images/plantation-femme-ouvriers.webp","alt":"Une femme en tenue verte plante un arbre, entourée des ouvriers du chantier","width":1600,"height":1066}'::jsonb, 'Des femmes découvrent et maîtrisent la technologie solaire pour éclairer leur foyer, développer une activité et transmettre leur savoir.', array['L''accès à l''énergie reste un défi dans de nombreuses communautés du Togo. Le projet « Femmes solaires » forme des femmes à la technologie solaire : comprendre une installation, l''utiliser, l''entretenir.', 'Ces compétences leur ouvrent des activités génératrices de revenus et renforcent leur place dans la communauté. Le projet fait le lien entre autonomisation des femmes, énergies renouvelables et protection de l''environnement.']::text[], '[{"label":"Public","value":"Femmes des communautés locales"},{"label":"Domaine","value":"Énergies renouvelables"},{"label":"Objectif","value":"Autonomie et revenus"}]'::jsonb, null, '[]'::jsonb, '[{"src":"/images/plantation-femme-ouvriers.webp","alt":"Une femme en tenue verte plante un arbre, entourée des ouvriers du chantier","width":1600,"height":1066},{"src":"/images/plantation-ambassade.webp","alt":"Plantation d''un arbre avec des officiels, un représentant de l''ambassade d''Allemagne et de jeunes femmes","width":1600,"height":1066}]'::jsonb, 2, true);
insert into public.posts (slug, title, published_on, category, image, excerpt, body, gallery, published) values
  ('premier-bloc-internat-acheve', 'Internat des jeunes filles : le premier bloc est achevé', '2025-12-01', 'Projets', '{"src":"/images/inauguration-ruban.webp","alt":"Coupe du ruban devant le bâtiment de l''internat, en présence d''un représentant de l''ambassade d''Allemagne","width":1600,"height":1066}'::jsonb, 'Fin 2025, le premier bloc de l''internat a été achevé. Il peut désormais accueillir 24 apprenties dans un cadre sûr et adapté au climat.', array['C''est une étape décisive pour le projet d''internat porté par KTGW Togo et ses partenaires : le premier bloc du bâtiment est achevé et peut accueillir 24 apprenties.', 'Construit en blocs de terre comprimée, le bâtiment est conçu pour le climat tropical. L''éclairage naturel et la gestion thermique assurent un confort durable sans surconsommation d''énergie.', 'Grâce à l''internat, des jeunes filles venues de loin peuvent suivre leur formation professionnelle sans trajets longs, coûteux et risqués. La suite du projet prévoit l''extension du bâtiment jusqu''à 16 chambres de 4 lits.']::text[], '[{"src":"/images/inauguration-ruban.webp","alt":"Coupe du ruban devant le bâtiment de l''internat, en présence d''un représentant de l''ambassade d''Allemagne","width":1600,"height":1066},{"src":"/images/invites-ceremonie.webp","alt":"Invités et partenaires togolais et allemands assis sous le chapiteau pendant la cérémonie","width":1600,"height":1066}]'::jsonb, true),
  ('richtfest-internat-13-avril-2023', 'Richtfest : la fête des ouvriers célébrée à l''internat', '2023-04-13', 'Vie de l''ONG', '{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066}'::jsonb, 'Le 13 avril 2023, partenaires togolais et allemands, autorités et ouvriers se sont réunis pour célébrer l''achèvement du gros œuvre de l''internat.', array['Le « Richtfest » est une tradition allemande : on célèbre la fin du gros œuvre d''un bâtiment en remerciant celles et ceux qui l''ont construit. Le 13 avril 2023, KTGW Togo a fait vivre cette tradition sur le chantier de l''internat pour jeunes filles.', 'La cérémonie a réuni les partenaires du projet (Togohilfe, un représentant de l''ambassade d''Allemagne et la Chambre des métiers de Cologne) ainsi que les autorités administratives, traditionnelles et religieuses.', 'Les ouvriers du chantier ont été mis à l''honneur : leur travail donne corps à un projet qui changera la vie de nombreuses apprenties.']::text[], '[{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066},{"src":"/images/photo-groupe-ouvriers.webp","alt":"Photo de groupe des officiels, partenaires et ouvriers en casques jaunes sous le chapiteau","width":850,"height":560},{"src":"/images/pretre-discours.webp","alt":"Un prêtre s''adresse à l''assemblée réunie sous le chapiteau","width":1600,"height":1066},{"src":"/images/invites-ceremonie.webp","alt":"Invités et partenaires togolais et allemands assis sous le chapiteau pendant la cérémonie","width":1600,"height":1066}]'::jsonb, true),
  ('plantations-arbres-internat', 'Des arbres plantés pour l''avenir de l''internat', '2023-04-13', 'Environnement', '{"src":"/images/plantation-ambassade.webp","alt":"Plantation d''un arbre avec des officiels, un représentant de l''ambassade d''Allemagne et de jeunes femmes","width":1600,"height":1066}'::jsonb, 'Lors de la cérémonie, partenaires, apprenties et officiels ont planté des arbres et un hibiscus autour du futur internat, un geste fort pour l''environnement.', array['La protection de l''environnement fait partie des objectifs de KTGW Togo. En marge de la fête des ouvriers, des arbres et un hibiscus ont été plantés autour du futur internat.', 'Partenaires allemands, représentants de l''ambassade, apprenties et ouvriers ont mis la main à la terre. Les plantations ont ensuite été bénies.', 'Ces arbres offriront de l''ombre et de la fraîcheur aux futures pensionnaires. Ils rappellent qu''éducation et environnement avancent ensemble.']::text[], '[{"src":"/images/plantation-ambassade.webp","alt":"Plantation d''un arbre avec des officiels, un représentant de l''ambassade d''Allemagne et de jeunes femmes","width":1600,"height":1066},{"src":"/images/plantation-hibiscus.webp","alt":"Deux personnes accroupies plantent un hibiscus en fleur","width":1600,"height":1066},{"src":"/images/plantation-partenaires.webp","alt":"Plantation d''un arbuste avec des partenaires allemands, une apprentie et les ouvriers du chantier","width":1600,"height":1066},{"src":"/images/plantation-femme-ouvriers.webp","alt":"Une femme en tenue verte plante un arbre, entourée des ouvriers du chantier","width":1600,"height":1066},{"src":"/images/benediction-plantation.webp","alt":"Bénédiction de la plantation par un prêtre, devant les ouvriers et les invités","width":1600,"height":1066}]'::jsonb, true);
insert into public.events (slug, title, starts_at, ends_at, venue, city, format, capacity, image, summary, body, is_sample, published) values
  ('portes-ouvertes-cefopexd', 'Journée portes ouvertes du CEFOPEXD', '2026-11-14T09:00:00+00', '2026-11-14T16:00:00+00', 'Centre CEFOPEXD', 'Devikinme', 'presentiel', 120, '{"src":"/images/photo-groupe-ouvriers.webp","alt":"Photo de groupe des officiels, partenaires et ouvriers en casques jaunes sous le chapiteau","width":850,"height":560}'::jsonb, 'Découvrez les ateliers, rencontrez les formateurs et informez-vous sur les inscriptions.', array['Le centre ouvre ses portes aux jeunes, aux familles et aux partenaires. Au programme : visite des ateliers, démonstrations et présentation des filières.', 'Une séance d''information sur les candidatures et l''internat pour jeunes filles aura lieu dans l''après-midi.']::text[], true, true),
  ('plantation-journee-benevolat', 'Grande plantation citoyenne', '2026-12-05T08:00:00+00', '2026-12-05T12:00:00+00', 'Siège de KTGW Togo, Tokoin Cébévito', 'Lomé', 'presentiel', 60, '{"src":"/images/plantation-hibiscus.webp","alt":"Deux personnes accroupies plantent un hibiscus en fleur","width":1600,"height":1066}'::jsonb, 'Une matinée de reboisement avec les apprenti·e·s, les bénévoles et les habitants du quartier.', array['À l''occasion de la Journée internationale des bénévoles, rejoignez-nous pour planter des arbres et sensibiliser au changement climatique.', 'Gants et plants fournis. Venez avec une gourde et un chapeau !']::text[], true, true),
  ('rencontre-clubs-allemand-2027', 'Rencontre des clubs d''allemand', '2027-01-23T10:00:00+00', '2027-01-23T15:00:00+00', 'En ligne et à Lomé', 'Lomé', 'en-ligne', 200, '{"src":"/images/invites-ceremonie.webp","alt":"Invités et partenaires togolais et allemands assis sous le chapiteau pendant la cérémonie","width":1600,"height":1066}'::jsonb, 'Échanges, jeux et présentations des élèves des clubs d''allemand, en lien avec des classes en Allemagne.', array['Les clubs de langue allemande des écoles togolaises présentent leurs projets et échangent en direct avec des élèves et bénévoles en Allemagne.']::text[], true, true),
  ('richtfest-internat-2023', 'Fête des ouvriers (Richtfest) de l''internat', '2023-04-13T09:00:00+00', null, 'Chantier de l''internat pour jeunes filles', 'Togo', 'presentiel', null, '{"src":"/images/discours-ouvriers.webp","alt":"Discours devant les ouvriers du chantier en gilets de sécurité, entre deux drapeaux du Togo","width":1600,"height":1066}'::jsonb, 'Célébration de l''achèvement du gros œuvre de l''internat avec les partenaires et les autorités.', array['Partenaires togolais et allemands, autorités administratives, traditionnelles et religieuses et ouvriers du chantier se sont réunis pour cette fête traditionnelle allemande.']::text[], false, true);
