insert into public.testimonials (quote, name, role, initials, is_sample, sort_order) values
  ('Avant, je n''avais pas de solution après l''école. Aujourd''hui, j''ai un métier entre les mains et je peux aider ma famille.', 'Apprentie', 'Formation en mécanique', 'AM', true, 0),
  ('L''internat a tout changé : je ne fais plus des heures de route chaque jour, je peux me concentrer sur ma formation.', 'Pensionnaire de l''internat', 'Formation en comptabilité', 'PI', true, 1),
  ('Apprendre l''allemand au club m''a ouvert l''esprit. J''ai échangé avec des jeunes de Cologne et je rêve de grands projets pour le Togo.', 'Élève du club d''allemand', 'Club de langue allemande', 'CA', true, 2);
